pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy a simple ERC20-like contract that will accept the call
        // We'll use a dummy contract that has transferFrom and always returns true
        address target = address(new Dummy());

        address[] memory tos = new address[](1);
        tos[0] = address(0x1234);
        uint[] memory vs = new uint[](1);
        vs[0] = 100;

        bool ok;
        try c.transfer(target, tos, vs) {
            ok = true;
        } catch {
            ok = false;
        }

        // Reference returns true, mutant returns false
        assertTrue(ok);
    }
}

contract Dummy {
    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address[] memory tos = new address[](2);
        tos[0] = address(0x1);
        tos[1] = address(0x2);
        uint[] memory vs = new uint[](1);
        vs[0] = 100;
        address contract_address = address(0x3);
        bool okReference;
        try c.transfer(contract_address, tos, vs) {
            okReference = true;
        } catch {
            okReference = false;
        }
        // The reference reverts because tos.length != vs.length
        assertTrue(!okReference);
    }
}

